    The links of a top bar in a row; the current one carries aria-current. side: all, or the first or second half of the list.
    Props (p): links, current, side. -#}
{%- set v_links = og_def(p['links'], none) -%}
{%- set v_current = og_def(p['current'], '') -%}
{%- set v_side = og_def(p['side'], 'all') -%}
{%- set v_count = og_len(v_links) -%}
{%- if og_t(og_gt(og_len(v_links), 0)) %}
  {%- set c_2 -%}
    {%- for v_l in og_l(v_links) %}
      {%- set v_i = loop.index0 -%}
      {%- if og_t(og_or([og_eq(v_side, 'all'), og_eq(og_lt(og_mul(v_i, 2), v_count), og_eq(v_side, 'left'))])) %}
        {%- set c_1 -%}
          {{ og_text(og_get(v_l, ['name'])) }}
        {%- endset -%}
        {{ og_include('blocks/menu-entry.html.j2', {'p': {'href': og_get(v_l, ['href']), 'className': og_cnv(['text-sm']), 'current': og_eq(og_get(v_l, ['id']), v_current), 'testid': 'nav-link'}, 'children': og_markup(c_1)}) }}
      {%- endif %}
    {%- endfor %}
  {%- endset -%}
  {{ og_include('compose/group.html.j2', {'p': {'Gap': '4', 'Align': 'center', 'Class': 'flex-wrap'}, 'children': c_2}) }}
{%- endif %}
